class Solution:

	def FindWays(self, n, m, blocked_cells):
		grid = [[1] * m for _ in range(n)]
		for (i, j) in blocked_cells:
			grid[i - 1][j - 1] = 0
		for i in range(1, n):
			grid[i][0] &= grid[i - 1][0]
		for j in range(1, m):
			grid[0][j] &= grid[0][j - 1]
		for i in range(1, n):
			for j in range(1, m):
				if grid[i][j]:
					grid[i][j] = grid[i - 1][j] + grid[i][j - 1]
		return grid[n - 1][m - 1] % (10 ** 9 + 7)
